import{b as t,O as a,g as n,j as e}from"./chunks/framework.DSt9LnBW.js";const k=JSON.parse('{"title":"腾讯文档 MCP 连接教程","description":"Lantern Harness 已经支持接入腾讯文档官方 MCP：配好 Token 后，工作台对话里就能搜、读、统计存储空间里的文档，不必再靠网页抓取。本文按「拿 Token → 配到工作台 → 对话里怎么用」走一遍。也可打开管理页（视账号是否开放）：docs.qq.com/open/auth/mcp.html","frontmatter":{"date":"2026-10-31T00:00:00.000Z","tags":["工具","MCP","腾讯文档","Lantern"],"sidebar":false,"pageClass":"blog-post","prev":false,"next":false,"lastUpdated":false},"headers":[],"relativePath":"blog/tools/tencent-docs-mcp/index.md","filePath":"个人博客/工具篇/11.腾讯文档MCP连接教程.md","lastUpdated":1793432020000}'),i={name:"blog/tools/tencent-docs-mcp/index.md"};function o(l,s,r,p,d,c){return a(),n("div",null,[...s[0]||(s[0]=[e(`<h1 id="腾讯文档-mcp-连接教程" tabindex="-1">腾讯文档 MCP 连接教程 <a class="header-anchor" href="#腾讯文档-mcp-连接教程" aria-label="Permalink to &quot;腾讯文档 MCP 连接教程&quot;">​</a></h1><p><a href="/blog/internet-years/lantern-harness-launch/">Lantern Harness</a> 已经支持接入腾讯文档官方 MCP：配好 Token 后，工作台对话里就能搜、读、统计存储空间里的文档，不必再靠网页抓取。</p><p>本文按「拿 Token → 配到工作台 → 对话里怎么用」走一遍。</p><p><img src="https://op.yychuiyan.com/docs-blog/tencent-docs-mcp-connect.png" alt="工作台对话测试腾讯文档 MCP：连接正常，根目录可读"></p><h2 id="一、前置条件" tabindex="-1">一、前置条件 <a class="header-anchor" href="#一、前置条件" aria-label="Permalink to &quot;一、前置条件&quot;">​</a></h2><table tabindex="0"><thead><tr><th>项</th><th>说明</th></tr></thead><tbody><tr><td>腾讯文档账号</td><td>QQ / 微信登录</td></tr><tr><td>存储空间</td><td>Token 绑在「存储空间」上；要用的文档须在该空间内（或空间内可访问）</td></tr><tr><td>Lantern Harness</td><td>本地服务已启动，并进入对应数据空间</td></tr><tr><td>会话工具</td><td>工作台会话允许使用工具（模型侧打开工具调用）</td></tr></tbody></table><p>补充几点：</p><ul><li><strong>没有存储空间</strong>：官方 MCP Token 一般拿不到，本文这套走不通。</li><li><strong>个人散落文档</strong>：建议移入或复制进存储空间；仅「快捷方式」不一定能稳定读到。</li><li><strong>会员与限额</strong>：获取 Token 时腾讯侧会校验超级会员 / 超级会员 Plus；日常还有日调用限额，超额后工具会失败。</li></ul><h2 id="二、在腾讯文档获取-mcp-token" tabindex="-1">二、在腾讯文档获取 MCP Token <a class="header-anchor" href="#二、在腾讯文档获取-mcp-token" aria-label="Permalink to &quot;二、在腾讯文档获取 MCP Token&quot;">​</a></h2><ol><li>电脑端打开 <a href="https://docs.qq.com" target="_blank" rel="noreferrer">腾讯文档</a>，登录。</li><li>左侧进入 <strong>「存储空间」</strong>（不要只停在「最近 / 云盘」的单篇文档页）。</li><li>点右上角 <strong>「≡」</strong>（或账号相关菜单）。</li><li>选 <strong>「使用 MCP」→「获取 MCP token」</strong>。</li><li>按页面提示复制 Token（约一年有效；可在同入口重置）。</li></ol><p><img src="https://op.yychuiyan.com/docs-blog/tencent-docs-mcp-get-token.png" alt="腾讯文档存储空间菜单：使用 MCP → 获取 MCP token"></p><p>也可打开管理页（视账号是否开放）：<a href="https://docs.qq.com/open/auth/mcp.html" target="_blank" rel="noreferrer">docs.qq.com/open/auth/mcp.html</a></p><p>官方说明：<a href="https://docs.qq.com/open/document/mcp/get-token/" target="_blank" rel="noreferrer">获取 MCP token</a></p><h2 id="三、在-lantern-harness-里配置" tabindex="-1">三、在 Lantern Harness 里配置 <a class="header-anchor" href="#三、在-lantern-harness-里配置" aria-label="Permalink to &quot;三、在 Lantern Harness 里配置&quot;">​</a></h2><ol><li>打开工作台，侧栏点 <strong>「插件」</strong>，进入 <strong>我的插件</strong>。</li><li>切到 <strong>「MCP」</strong> Tab。</li><li>列表默认有一行 <strong>「腾讯文档」</strong>（<code>tencent-docs</code>）。 <ul><li>未配 Token：状态为 <strong>「需配置」</strong> → 点 <strong>「配置」</strong>。</li><li>已配置：可点 <strong>「编辑」</strong> 更换 Token。</li></ul></li><li>弹窗中： <ul><li><strong>名称</strong>：<code>tencent-docs</code>（预填，一般不用改）</li><li><strong>URL</strong>：<code>https://docs.qq.com/openapi/mcp</code>（预填）</li><li><strong>MCP Token（Authorization）</strong>：粘贴刚才复制的 Token</li></ul></li><li>点 <strong>「保存」</strong>。</li><li>列表状态应变为 <strong>「已连接」</strong>；「工具」列显示的是该 MCP <strong>提供的工具数量</strong>（例如 200+），<strong>不是</strong>调用次数。</li></ol><p>配置落在当前数据空间：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>&lt;数据空间&gt;/.lantern/local/mcp.json</span></span></code></pre></div><p>示例结构：</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;servers&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    {</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">      &quot;name&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;tencent-docs&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">      &quot;transport&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;http&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">      &quot;url&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;https://docs.qq.com/openapi/mcp&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">      &quot;headers&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">        &quot;Authorization&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;&lt;你的 MCP Token&gt;&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">      }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  ]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>补充：</p><ul><li>每个 <strong>数据空间</strong> 各有一份 <code>mcp.json</code>，互不影响。</li><li>腾讯文档侧 Token 绑的是 <strong>腾讯存储空间</strong>；换腾讯空间要换 Token。</li><li>腾讯文档这条不需要填 <code>env</code>；<code>env</code> 是给本机 stdio 类 MCP（部分第三方服务）用的。</li><li>加其它 MCP 可用「添加 MCP」，支持表单，或粘贴 Trae / Claude 风格的 <code>mcpServers</code> JSON。</li></ul><h2 id="四、对话里怎么用" tabindex="-1">四、对话里怎么用 <a class="header-anchor" href="#四、对话里怎么用" aria-label="Permalink to &quot;四、对话里怎么用&quot;">​</a></h2><ol><li>回到 <strong>我的工作台</strong> 对话（不要停在插件页）。</li><li>用自然语言说明要读哪类文档，并点明走腾讯文档 MCP，例如：</li></ol><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>用腾讯文档 MCP：</span></span>
<span class="line"><span>1. 在空间里找到「缺陷管理」文档，拿到 file_id；</span></span>
<span class="line"><span>2. 如果是智能表格，先 list_tables / list_fields，再用 list_records 拉记录；</span></span>
<span class="line"><span>3. 统计「政企通」相关缺陷数量，按严重程度汇总。</span></span>
<span class="line"><span>不要用 web_fetch 打开 docs.qq.com（要登录，读不到）。</span></span></code></pre></div><p>更简单的试探：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>用腾讯文档 MCP，列出当前存储空间根目录有哪些文件。</span></span></code></pre></div><p>对话中应出现 <code>mcp__tencent-docs__…</code> 形式的工具调用。</p><h2 id="五、「已连接」但取不到数据" tabindex="-1">五、「已连接」但取不到数据？ <a class="header-anchor" href="#五、「已连接」但取不到数据" aria-label="Permalink to &quot;五、「已连接」但取不到数据？&quot;">​</a></h2><table tabindex="0"><thead><tr><th>现象</th><th>原因 / 处理</th></tr></thead><tbody><tr><td>搜索报 <code>modify_time</code> / <code>total</code> 类型错误</td><td>腾讯侧搜索接口已知问题；改用空间节点树、最近浏览，或已知 <code>file_id</code> 直接读</td></tr><tr><td>智能表格读不全</td><td>缺陷类表多为 <strong>smartsheet</strong>，需 <code>list_tables</code> → <code>list_records</code>，不能只靠普通 <code>get_content</code></td></tr><tr><td>快捷方式读失败</td><td>改成真文件放入存储空间</td></tr><tr><td><code>web_fetch</code> 打开文档链接失败</td><td>正常；必须走 MCP 工具，不要走网页抓取</td></tr><tr><td>偶发失败</td><td>检查日调用限额；点「刷新连接」后重试</td></tr></tbody></table><p>再强调一次：「工具」列的数字 = <strong>可用工具个数</strong>，≠ 已调用次数。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><p>整条链路很短：在腾讯文档<strong>存储空间</strong>拿 MCP Token → 贴进 Lantern「我的插件 → MCP」→ 对话里点名走腾讯文档 MCP。文档要落在对应存储空间里，智能表格走 <code>list_tables</code> / <code>list_records</code>，别用 <code>web_fetch</code> 硬扒网页。</p>`,32)])])}const g=t(i,[["render",o]]);export{k as __pageData,g as default};
